WITH not_flagged AS (SELECT s.* FROM orders s WHERE NOT EXISTS (SELECT 1 FROM order_items ch WHERE ch.order_id = s.id AND ch.product_id = 19)) SELECT CASE WHEN discount >= 0.32 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, CASE WHEN shipping_fee >= 44 THEN 'LARGE' ELSE 'SMALL' END AS shipping_fee_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, ROUND(AVG(shipping_fee), 2) AS avg_shipping_fee, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count FROM not_flagged GROUP BY GROUPING SETS ((CASE WHEN discount >= 0.32 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN shipping_fee >= 44 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN discount >= 0.32 THEN 'HIGH' ELSE 'LOW' END), ()) HAVING COUNT(CASE WHEN channel = 'store' THEN 1 END) > 1
